#include <bits/stdc++.h>

using namespace std;

int main() {
    int n, m, x;
    cin >> n >> m;

    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> x;
        arr[i] = x;
    }

    int maxim = 0;
    for (int j = 0; j < n; ++j) {
        maxim = max(maxim, arr[j]);
    }

    int raz;
    for (int g = 0; g < n; ++g) {
        raz = maxim - arr[g];
        m -= raz;
    }

    int minimal;
    if (m < 0) {
        minimal = maxim;
    } else {
        int plus = m / n;
        minimal = maxim + plus;
    }

    cout << minimal << maxim + m;
    return 0;
}

