    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    long long sum = 0, maximum = 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        sum += x;
        maximum = max(maximum, x);
    }

    long long minimum = max(maximum, (sum + m + n - 1) / n);
    cout << minimum << ' ' << maximum + m;

    return 0;
}

